import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] w = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) { w[i] = sc.nextLong(); total += w[i]; }
        long[] s = new long[1 << n];
        long best = total;
        for (int m = 1; m < (1 << n); m++) {
            int low = m & -m;
            s[m] = s[m ^ low] + w[Integer.numberOfTrailingZeros(low)];
            best = Math.min(best, Math.abs(total - 2 * s[m]));
        }
        System.out.println(best);
    }
}

