#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> w(n);
    long long total = 0;
    for (auto &v : w) {
        cin >> v;
        total += v;
    }
    vector<long long> s(1 << n, 0);
    long long best = total;
    for (int m = 1; m < (1 << n); m++) {
        int low = m & -m;
        s[m] = s[m ^ low] + w[__builtin_ctz(m)];
        best = min(best, llabs(total - 2 * s[m]));
    }
    cout << best << endl;
    return 0;
}
